// فصل 11 از کتاب — تبدیل‌شده از نسخهٔ HTML؛ ویرایش دستی لازم نیست.
// Chapter 11 of the book — converted from the HTML edition; generated file.

export const n = 11;
export const num = "11";
export const title = "Source Control فوق‌پیشرفته — Graph تا PR";
export const label = "فصل ۱۱ · Source Control پیشرفته";
export const part = 1;
export const html = "<p class=\"lead\">Graph، شاخه، Sync، تعارض، rebase و PR همه از همان Ctrl+Shift+G می‌آیند. مثل فصل ۱۰: هر کار یعنی چند کلیک مشخص، چه باید ببینی، و اگر مال تو فرق داشت یعنی چه.</p>\n  <h2><span class=\"hx\"><span class=\"hx-t\">🎯 اهداف یادگیری</span></span></h2>\n<ul>\n<li>Graph را با کلیک باز کنی و از راست‌کلیک روی کامیت نترسی</li>\n<li>Fetch / Pull / Push / Sync را از روی منو جدا بزنی و بدانی چرا دکمهٔ تو با کتاب یکی نیست</li>\n<li>تعارض و rebase را تا آخرین کلیک (Continue یا Abort) تمام کنی</li>\n<li>اگر Graph، Incoming یا افزونهٔ PR نبود، علت را بدانی</li>\n</ul>\n<h2><span class=\"hx\"><span class=\"hx-t\">📈 Graph — باز کردن و راست‌کلیک</span></span></h2>\n<p><strong>کلیک‌ها برای باز شدن:</strong></p>\n<ol>\n<li><code>Ctrl+Shift+G</code>.</li>\n<li>ته ستون Source Control روی <strong>Graph</strong> یک کلیک (اگر <code>&gt;</code> دیدی، همان را باز کن).</li>\n<li class=\"keep-next\">اگر Graph نبود: <code>Ctrl+Shift+P</code> → <code>Git: View History</code> → Enter.</li>\n</ol>\n<div class=\"shot zoom\">\n<img src=\"/book/figures/vscode-scm-graph-zoom.png\" alt=\"Source Control Graph نزدیک\"/>\n<p class=\"figcap\">شکل ۱۱ — برش نزدیک. رنگ‌ها و هش‌ها مثال‌اند؛ تو کامیت‌های مخزن خودت را می‌بینی.</p>\n</div>\n<p><strong>باید ببینی:</strong> خط‌های رنگی، هش کوتاه، پیام کامیت، گاهی برچسب <code>main</code> / <code>HEAD</code>.</p>\n<p class=\"keep-next\"><strong>اگر مال تو این‌طور نیست:</strong></p>\n<div class=\"tbl-wrap\"><table><thead>\n<tr>\n<th>چه دیدی</th>\n<th>علت</th>\n<th>چه کار کن</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>اصلاً Graph در ستون نیست</td>\n<td>VS Code قدیمی‌تر از حدود ۱.۹۷</td>\n<td>VS Code را به‌روز کن؛ یا افزونهٔ Git Graph / GitLens</td>\n</tr>\n<tr>\n<td>Graph باز شد ولی یک نقطه است</td>\n<td>مخزن فقط یک کامیت دارد</td>\n<td>طبیعی است</td>\n</tr>\n<tr>\n<td>Incoming خالی است با اینکه همکار push کرده</td>\n<td>Fetch نشده</td>\n<td>منوی <code>···</code> → Fetch (پایین)</td>\n</tr>\n<tr>\n<td>راست‌کلیک منوی کوتاه دارد</td>\n<td>روی پیام کلیک کرده‌ای نه روی گره، یا افزونه منو را عوض کرده</td>\n<td>روی دایرهٔ کامیت راست‌کلیک کن</td>\n</tr>\n</tbody>\n</table></div><p class=\"keep-next\"><strong>راست‌کلیک روی یک دایره / ردیف کامیت، بعد یک کلیک روی فرمان:</strong></p>\n<div class=\"tbl-wrap\"><table><thead>\n<tr>\n<th>فرمان</th>\n<th>بعد از کلیک چه می‌شود</th>\n<th>اگر ترسیدی</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Checkout</td>\n<td>HEAD می‌رود روی آن کامیت</td>\n<td>اگر شاخه نبود، نوار زرد detached می‌آید → فوری Create Branch</td>\n</tr>\n<tr>\n<td>Create Branch</td>\n<td>جعبهٔ نام می‌پرسد</td>\n<td>Enter بزن؛ معادل <code>git switch -c</code></td>\n</tr>\n<tr>\n<td>Cherry Pick</td>\n<td>یک کامیت جدید روی شاخهٔ فعلی</td>\n<td>تعارض آمد = فصل تعارض همین صفحه</td>\n</tr>\n<tr>\n<td>Revert</td>\n<td>یک کامیت خنثی‌کننده می‌سازد</td>\n<td>برای <code>main</code> مشترک همین را بزن نه Reset</td>\n</tr>\n<tr>\n<td>Reset Current Branch to Here</td>\n<td>می‌پرسد Soft/Hard</td>\n<td>Hard را روی شاخهٔ مشترک نزن</td>\n</tr>\n<tr>\n<td>Compare with HEAD</td>\n<td>diff باز می‌شود</td>\n<td>بی‌خطر</td>\n</tr>\n</tbody>\n</table></div><h2><span class=\"hx\"><span class=\"hx-t\">🌿 عوض کردن و ساختن شاخه — از نوار وضعیت</span></span></h2>\n<p class=\"keep-next\"><strong>کلیک ۱:</strong> پایین-چپ پنجره، روی <strong>نام شاخه</strong> (مثلاً <code>main</code>).<br />\n<strong>باید ببینی:</strong> فهرست بالا وسط ادیتور (Quick Pick).</p>\n<div class=\"shot\">\n<img src=\"/book/figures/vscode-branch-picker.png\" alt=\"انتخاب شاخه در نوار وضعیت VS Code\"/>\n<p class=\"figcap\">شکل ۱۱ب — اگر این فهرست نیامد، روی نام شاخه کلیک نشده یا Git پیدا نشده.</p>\n</div>\n<p><strong>کلیک ۲ — تعویض:</strong> روی نام شاخهٔ دیگر.<br />\n<strong>باید ببینی:</strong> نوار وضعیت همان نام را می‌گیرد؛ فایل‌های ادیتور عوض می‌شوند.</p>\n<p><strong>اگر خطا Your local changes would be overwritten:</strong> تغییرات ذخیره‌شده داری. اول Commit یا Stash (منوی <code>···</code> → Stash)، بعد دوباره نام شاخه را کلیک کن.</p>\n<p class=\"keep-next\"><strong>کلیک ۲ — ساختن:</strong> روی <code>+ Create new branch from...</code> → یک کلیک روی پایه‌ای که می‌خواهی (<code>main</code>) → نام را تایپ کن مثلاً <code>feat/auth</code> → Enter.</p>\n<div class=\"shot\">\n<img src=\"/book/figures/vscode-create-branch.png\" alt=\"ساخت شاخه از Command Palette\"/>\n<p class=\"figcap\">شکل ۱۱پ — همین کار از Palette با Git: Create Branch from... هم می‌شود.</p>\n</div>\n<p><strong>کلیک Publish Branch:</strong> در همان فهرست یا روی دکمهٔ ابری نوار وضعیت. اولین push است (<code>-u</code>).</p>\n<p><strong>اگر Publish می‌خواهد وارد GitHub شوی:</strong> Accounts پایین Activity Bar → Sign in. بدون origin، دکمهٔ اصلی پنل به‌جای Sync می‌ماند Publish.</p>\n<p><strong>اگر شاخهٔ جدید در فهرست نیست:</strong> هنوز Enter ساختن را نزدی، یا <code>refresh</code> لازم است: <code>···</code> → Refresh.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">📡 منوی ··· — هر فرمان یک کلیک، Sync آخرین انتخاب</span></span></h2>\n<p class=\"keep-next\"><strong>کلیک:</strong> بالا-راست ستون Source Control روی <code>···</code> (شمارهٔ ۲ آناتومی فصل ۱۰).</p>\n<div class=\"shot zoom\">\n<img src=\"/book/figures/vscode-scm-menu-zoom.png\" alt=\"منوی Fetch Pull Stash در Source Control\"/>\n<p class=\"figcap\">شکل ۱۱ت — ترتیب پیشنهادی: اول Fetch، نگاه به ↓↑، بعد Pull یا Push. Sync میان‌بر هر دوست.</p>\n</div>\n<div class=\"tbl-wrap\"><table><thead>\n<tr>\n<th>کلیک روی</th>\n<th>باید بعدش ببینی</th>\n<th>مال تو فرق دارد اگر</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Fetch</td>\n<td>عدد ↓ در نوار وضعیت زیاد شود، Graph Incoming پر شود؛ فایل‌ها عوض نمی‌شوند</td>\n<td>اینترنت/SSH نیست؛ یا origin نداری</td>\n</tr>\n<tr>\n<td>Pull</td>\n<td>فایل‌ها ممکن است عوض شوند؛ ↓ صفر شود</td>\n<td>تعارض → بخش بعد. اگر rebaseWhenSync روشن باشد ممکن است rebase شروع شود</td>\n</tr>\n<tr>\n<td>Pull (Rebase)</td>\n<td>اگر تعارض باشد نوار زرد Rebase</td>\n<td>روی <code>main</code> مشترک نزن</td>\n</tr>\n<tr>\n<td>Push</td>\n<td>↑ صفر شود</td>\n<td>rejected = کسی push کرده؛ Fetch کن نه Force</td>\n</tr>\n<tr>\n<td>Sync</td>\n<td>ترکیب pull/push</td>\n<td>اگر confirmSync روشن باشد یک Yes اضافه می‌پرسد — این «خراب بودن» نیست</td>\n</tr>\n<tr>\n<td>Stash (Include Untracked)</td>\n<td>Changes خالی می‌شود</td>\n<td>بدون Include، فایل‌های U می‌مانند و switch شکست می‌خورد</td>\n</tr>\n<tr>\n<td>Undo Last Commit</td>\n<td>فایل‌ها برمی‌گردند به Staged</td>\n<td>اگر push کرده باشی، بعداً Push rejected می‌شود</td>\n</tr>\n<tr>\n<td>Discard All Changes</td>\n<td>همهٔ فایل‌های M از لیست می‌روند</td>\n<td>پنجرهٔ Are you sure؟ — Yes یعنی از دست رفتن کار ذخیره‌نشده</td>\n</tr>\n</tbody>\n</table></div><p>نوار وضعیت <code>↑1 ↓2</code> یعنی ۱ کامیت برای push و ۲ برای pull. <strong>عدد تو با کتاب یکی نمی‌شود</strong> و نباید بشود.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">💥 تعارض — از حرف C تا Commit (merge)</span></span></h2>\n<p>تعارض فقط بعد از Merge / Pull / Cherry-pick / Rebase می‌آید. اگر هیچ‌کدام را نزدی و C دیدی، احتمالاً merge ناتمام قبلی مانده: Palette → <code>Git: Abort Merge</code>.</p>\n<p class=\"keep-next\"><strong>باید ببینی:</strong> در Source Control عنوان <strong>Merge Changes</strong> و فایل با حرف <strong>C</strong>. دکمهٔ اصلی ممکن است بشود <strong>Accept Merge</strong> / <strong>Commit (merge)</strong>.</p>\n<div class=\"shot zoom\">\n<img src=\"/book/figures/vscode-scm-conflict-zoom.png\" alt=\"تعارض در Source Control و ادیتور\"/>\n<p class=\"figcap\">شکل ۱۱ث — نوار آبی چهار فرمان فقط روی فایل C بازشده از Source Control است.</p>\n</div>\n<p><strong>کلیک‌ها:</strong></p>\n<ol>\n<li><strong>یک کلیک</strong> روی فایل C.</li>\n<li>بالای بلوک قرمز/سبز، <strong>یک کلیک</strong> روی یکی از:\n<ul>\n<li><strong>Accept Current Change</strong> = نسخهٔ شاخه‌ای که روی آن بودی (<code>HEAD</code> / Ours)</li>\n<li><strong>Accept Incoming Change</strong> = نسخه‌ای که داشتی وارد می‌کردی (Theirs)</li>\n<li><strong>Accept Both Changes</strong> = هر دو پشت‌سرهم؛ بعد خودت ویرایش کن</li>\n<li><strong>Compare Changes</strong> = دو ستون</li>\n</ul>\n</li>\n<li><code>Ctrl+S</code>.</li>\n<li><strong>یک کلیک روی <code>+</code></strong> همان فایل (Stage). حرف C باید برود.</li>\n<li><strong>یک کلیک روی Commit (merge)</strong> یا Ctrl+Enter با پیام پیش‌فرض merge.</li>\n</ol>\n<p><strong>اگر نوار Accept نبود:</strong> Palette → <code>Merge Conflict: Open Merge Editor</code> — سه ستون Incoming / Current / Result. Result را درست کن → <strong>Accept Merge</strong>.</p>\n<p><strong>اگر هنوز C می‌ماند:</strong> Save و Stage را نزدی. یا چند تعارض در همان فایل است — همه را Accept کن.</p>\n<p><strong>پشیمانی قبل از مرحلهٔ ۵:</strong> Palette → <code>Git: Abort Merge</code>. بعد از Commit دیگر abort نیست؛ باید revert.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">🔁 Rebase ناتمام — نوار زرد را تا انتها دنبال کن</span></span></h2>\n<p>بعد از <strong>Pull (Rebase)</strong> یا <code>Git: Rebase Branch...</code> اگر تعارض باشد:</p>\n<p class=\"keep-next\"><strong>باید ببینی:</strong> در پنل «Rebase in progress»، در بالا ادیتور نوار زرد، دکمه‌های Continue / Abort.</p>\n<div class=\"shot zoom\">\n<img src=\"/book/figures/vscode-scm-rebase-zoom.png\" alt=\"Rebase in progress در Source Control\"/>\n<p class=\"figcap\">شکل ۱۱ج — تا این نوار هست، دکمهٔ معمولی Commit را نزن. VS Code عمداً کامیت عادی را قفل یا گمراه‌کننده می‌کند.</p>\n</div>\n<p><strong>کلیک‌ها:</strong></p>\n<ol>\n<li>فایل C را مثل تعارض حل کن → Save → <code>+</code> (Stage).</li>\n<li><strong>یک کلیک Continue</strong> (= <code>git rebase --continue</code>).</li>\n<li>اگر تعارض بعدی آمد، ۱ و ۲ را تکرار کن تا نوار زرد برود.</li>\n</ol>\n<p><strong>اگر Continue خاکستری است:</strong> هنوز همهٔ فایل‌های C را Stage نکرده‌ای، یا Message rebase خالی است — جعبهٔ Message را خالی نگذار.</p>\n<p><strong>پشیمانی:</strong> یک کلیک <strong>Abort</strong>. همه چیز برمی‌گردد به قبل از rebase.</p>\n<p><strong>اگر وسط rebase VS Code را بستی و باز کردی:</strong> نوار زرد باید برگردد. اگر نماند، Palette → <code>Git: Continue Rebase</code> یا <code>Abort Rebase</code>.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">📚 چند مخزن در یک پنجره</span></span></h2>\n<p><strong>کلیک‌ها:</strong> <code>File → Add Folder to Workspace</code> → پوشهٔ دوم که خودش <code>.git</code> دارد.</p>\n<p class=\"keep-next\"><strong>باید ببینی:</strong> در Source Control چند عنوان Repository. یک کلیک روی عنوان، آن مخزن را جمع/باز می‌کند.</p>\n<div class=\"shot zoom\">\n<img src=\"/book/figures/vscode-scm-multirepo-zoom.png\" alt=\"چند مخزن در Source Control\"/>\n<p class=\"figcap\">شکل ۱۱چ — اگر فقط یکی می‌بینی، پوشهٔ دوم Git ندارد یا هنوز Add Folder نکرده‌ای.</p>\n</div>\n<p><strong>اگر Commit روی مخزن غلط نشست:</strong> عنوان همان Repository را باز کن، بعد Message را بزن. VS Code روی مخزن «فعال» کامیت می‌کند.</p>\n<p>worktree: در ترمینال <code>git worktree add -b hotfix/500 ../hotfix main</code> بعد <code>File → Add Folder</code> روی <code>../hotfix</code>. یک شاخه در دو worktree هم‌زمان باز نمی‌شود — پیام خطا را با Stash یا عوض کردن شاخه حل کن.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">📬 Pull Request — افزونه، نه خود Git توکار</span></span></h2>\n<p>Source Control توکار PR نمی‌سازد. باید افزونهٔ <strong>GitHub Pull Requests</strong> نصب باشد.</p>\n<p><strong>کلیک نصب:</strong> Activity Bar آیکون Extensions (یا <code>Ctrl+Shift+X</code>) → جست‌وجو <code>GitHub Pull Requests</code> → Install → Accounts پایین Activity Bar → <strong>Sign in to GitHub</strong> → مرورگر Allow.</p>\n<p class=\"keep-next\"><strong>اگر آیکون GitHub در Activity Bar نیامد:</strong> افزونه نصب نشده یا غیرفعال است. View → Appearance → Activity Bar را چک کن.</p>\n<div class=\"shot\">\n<img src=\"/book/figures/vscode-pr-ext.png\" alt=\"بررسی Pull Request داخل VS Code\"/>\n<p class=\"figcap\">شکل ۱۲ — این نما مال افزونه است نه ستون Git. اگر ندیدی، Sign in نشده.</p>\n</div>\n<p><strong>ساخت PR از شاخهٔ فعلی:</strong></p>\n<ol>\n<li>اول Push / Publish Branch از Source Control (وگرنه GitHub شاخه را ندارد).</li>\n<li><code>Ctrl+Shift+P</code> → <code>GitHub Pull Requests: Create Pull Request</code>.</li>\n<li>عنوان و پایه (<code>main</code>) را تأیید کن → Create.</li>\n</ol>\n<p><strong>اگر Create خطا می‌دهد no upstream:</strong> Publish Branch را جا انداختی.</p>\n<p><strong>ریویو:</strong> آیکون GitHub → یک کلیک روی PR → Checkout → در Files Changed روی خط کلیک → کامنت → Approve.</p>\n<p><strong>اگر Checkout PR فایل‌های تو را overwrite می‌کند:</strong> اول Commit یا Stash از ستون Source Control.</p>\n<h2><span class=\"hx\"><span class=\"hx-t\">⚙️ اگر رفتار پنل «عجیب» است، اول این تنظیمات را چک کن</span></span></h2>\n<p class=\"keep-next\"><code>Ctrl+,</code> → جست‌وجوی هر کلید:</p>\n<div class=\"code\"><div class=\"code-head\"><span class=\"dots\"><i></i><i></i><i></i></span><span class=\"fname\">.vscode/settings.json — رفتار SCM</span></div><pre><span style=\"color: #F8F8F2\">{</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;git.enabled&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #66D9EF\">true</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;git.autofetch&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #66D9EF\">true</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;git.confirmSync&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #66D9EF\">true</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;git.enableSmartCommit&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #66D9EF\">false</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;git.enableCommitSigning&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #66D9EF\">true</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;git.untrackedChanges&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #E6DB74\">&quot;separate&quot;</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;git.branchProtection&quot;</span><span style=\"color: #F8F8F2\">: [</span><span style=\"color: #E6DB74\">&quot;main&quot;</span><span style=\"color: #F8F8F2\">, </span><span style=\"color: #E6DB74\">&quot;master&quot;</span><span style=\"color: #F8F8F2\">],</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;git.branchProtectionPrompt&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #E6DB74\">&quot;alwaysCommitToNewBranch&quot;</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;git.rebaseWhenSync&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #66D9EF\">false</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;git.autoStash&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #66D9EF\">true</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;scm.defaultViewMode&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #E6DB74\">&quot;tree&quot;</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;scm.repositories.visible&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #AE81FF\">8</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;diffEditor.ignoreTrimWhitespace&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #66D9EF\">false</span><span style=\"color: #F8F8F2\">,</span>\n<span style=\"color: #F8F8F2\">  </span><span style=\"color: #FF4689\">&quot;diffEditor.hideUnchangedRegions.enabled&quot;</span><span style=\"color: #F8F8F2\">: </span><span style=\"color: #66D9EF\">true</span>\n<span style=\"color: #F8F8F2\">}</span>\n</pre></div>\n<div class=\"tbl-wrap\"><table><thead>\n<tr>\n<th>دیدی</th>\n<th>احتمالاً این تنظیم</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Commit بدون <code>+</code> همه را برد</td>\n<td><code>enableSmartCommit</code> روشن — Off کن</td>\n</tr>\n<tr>\n<td>روی <code>main</code> کامیت زدی، VS Code شاخهٔ جدید ساخت</td>\n<td><code>branchProtection</code> — عمدی است</td>\n</tr>\n<tr>\n<td>Sync ناگهان rebase شروع کرد</td>\n<td><code>rebaseWhenSync</code> روشن</td>\n</tr>\n<tr>\n<td>قبل از Pull فایل‌ها ناپدید شدند و بعد برگشتند</td>\n<td><code>autoStash</code> — stash موقت، ترس ندارد</td>\n</tr>\n<tr>\n<td>Untracked ته لیست قاطی است</td>\n<td><code>untrackedChanges</code> را <code>separate</code> کن</td>\n</tr>\n<tr>\n<td>هر Sync یک دیالوگ Yes/No</td>\n<td><code>confirmSync</code> — سلیقه است</td>\n</tr>\n</tbody>\n</table></div><h2><span class=\"hx\"><span class=\"hx-t\">⌨️ Palette — وقتی کلیک را پیدا نمی‌کنی</span></span></h2>\n<p><code>Ctrl+Shift+P</code>، تایپ <code>Git:</code>، Enter روی فرمان. اگر فرمان در فهرست نیست: یا پوشه مخزن ندارد، یا Git پیدا نشده (<code>Git: Show Git Output</code>).</p>\n<p><code>Stage All Changes</code> · <code>Commit</code> · <code>Undo Last Commit</code> · <code>Push</code> · <code>Pull</code> · <code>Pull (Rebase)</code> · <code>Fetch</code> · <code>Sync</code> · <code>Create Branch from...</code> · <code>Checkout to...</code> · <code>Merge Branch...</code> · <code>Rebase Branch...</code> · <code>Publish Branch</code> · <code>Stash</code> · <code>Continue Rebase</code> · <code>Abort Rebase</code> · <code>Abort Merge</code> · <code>View History</code> · <code>Show Git Output</code></p>\n<div class=\"callout callout-interview\"><div class=\"callout-title\">سؤالات مصاحبه (با پاسخ)</div>\n<p><strong>Mid — چرا Sync من merge ساخت و مال همکار rebase؟</strong> تنظیم <code>git.rebaseWhenSync</code> فرق دارد. از روی دکمه حدس نزن؛ منوی <code>···</code> را بخوان.</p>\n<p><strong>Senior — Checkout PR چه کلیک‌هایی زیرش است؟</strong> Sign in، fetch همان ref، switch به آن شاخه. اگر Changes خالی نبود، VS Code اول Stash/Commit می‌خواهد.</p>\n</div>\n<h2><span class=\"hx\"><span class=\"hx-t\">✅ چک‌لیست فهم</span></span></h2>\n<div class=\"keep-block\"><div class=\"checklist\">\n<ul>\n<li>Graph را باز کرده‌ای و اگر نبود علت را بلدی</li>\n<li>از روی <code>···</code> یک Fetch جدا زده‌ای نه فقط Sync</li>\n<li>یک فایل C را تا Commit (merge) یا Abort برده‌ای</li>\n<li>نوار زرد rebase را Continue یا Abort کرده‌ای نه Commit عادی</li>\n<li>اگر PR نبود، فرق افزونه با Source Control توکار را می‌دانی</li>\n</ul>\n</div><p><strong>فصل بعد:</strong> diff، blame، log و bisect — دیدن تغییر با چشم مسلح.</p></div>";
export default { n, num, title, label, part, html };
